class Registry {
public:
    void add(std::string s) { entries().push_back(std::move(s)); }
    const std::vector<std::string>& all() const { return entries(); }
private:
    static std::vector<std::string>& entries() {   // C++11: exactly once
        static std::vector<std::string> data;
        return data;
    }
};
